import AppKit
import SwiftUI

/// 折角贴图：一张 42pt（3 倍图 126x126）的透明 PNG，画的是纸角自然卷起的效果。
/// 为什么是图不是代码画：0.3.2 的代码画版本在快照上看着达标、真机上太淡；
/// 代码到真机之间有一层「翻译」，渐变与模糊的实际渲染验不准。
/// 图是像素级保真：渲出来什么样，装上就是什么样。
/// 图是 base64 嵌在代码里的——GitHub API 推不了二进制文件，所以不用 Resources/，
/// 也不用 Carry 本地放图。源文件在 workspace/stickyside-app-ui/FoldCorner-c.png，
/// 设计见 fold-prototype-v2-2026-11-13.html（v2c：淡白翻面 0.7 + 薄影 0.15）。
/// 图本身是纸色无关的：翻面是白色带透明度（叠在黄纸上是淡黄、叠在薄荷纸上是淡绿），
/// 影子是黑色带透明度；一张图通吃六色纸与深浅两模式。42pt 固定尺寸，卡片多大都不拉伸。
enum FoldImage {
    static let size: CGFloat = 42

    private static let base64 = ""

    /// 解不出来返回 nil，调用方回退到代码画的旧折角（FoldFlapShape/FoldShadowShape）。
    static var nsImage: NSImage? {
        guard let data = Data(base64Encoded: base64),
              let image = NSImage(data: data) else { return nil }
        // 126px / 42pt = 3 倍图，显式标成 42pt，Retina 上清晰。
        image.size = NSSize(width: size, height: size)
        return image
    }
}
